INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN('subcontract_certificates.view','subcontract_certificates.create','subcontract_certificates.edit','subcontract_certificates.approve','subcontract_certificates.cancel') WHERE r.code='super_admin' ON DUPLICATE KEY UPDATE role_id=VALUES(role_id);
